mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  float t = time * 0.8;
  vec3 col = vec3(0.02, 0.01, 0.04);
  for (float i = 0.0; i < 8.0; i += 1.0) {
    float y = sin(p.x * (2.0 + i) + t + i * 0.8) * 0.4;
    float dist = abs(p.y - y);
    vec3 threadCol = 0.5 + 0.5 * cos(vec3(0.0, 1.5, 3.0) + i + t);
    col += threadCol * (0.008 / (0.01 + dist * dist * 8.0));
  }
  col *= (1.0 + 0.4 * bass);
  ret = col;
}
